-- Part 1 of 3. Content routines from /content (strength + stretch).
-- Paste this file, then content_routines_2.sql, then content_routines_3.sql.
-- Safe to run again. Never deletes sessions, sets, enrolments, profiles
-- or the original 14 routine ids (gym-confidence-6 and friends).
-- Adds the 15 strength plans and stretch sessions, with weeks and days.
-- Exercise slots are in parts 2 and 3.
-- Adds any missing exercises used by those plans. Existing exercise
-- rows keep their id so logged history stays linked.

-- Columns the seed writes. No-ops if you have already pasted n2 / stretches.
alter table public.routines add column if not exists type text;
update public.routines set type = 'strength' where type is null;
alter table public.routines alter column type set default 'strength';
alter table public.routines drop constraint if exists routines_session_minutes_check;
alter table public.routines add constraint routines_session_minutes_check check (
  session_minutes between 5 and 120
);

alter table public.routines add column if not exists audience_bullets text[];
alter table public.routines add column if not exists by_the_end_bullets text[];
alter table public.routines add column if not exists split_note text;
alter table public.routines add column if not exists progression_note text;

alter table public.routine_weeks add column if not exists is_checkpoint boolean not null default false;
alter table public.routine_weeks add column if not exists phase_name text;
alter table public.routine_weeks add column if not exists phase_goal text;
alter table public.routine_weeks add column if not exists is_lighter_week boolean;
update public.routine_weeks set is_lighter_week = false where is_lighter_week is null;
alter table public.routine_weeks alter column is_lighter_week set default false;

alter table public.routine_days add column if not exists focus text;
alter table public.routine_days add column if not exists warmup jsonb;
alter table public.routine_days add column if not exists coach_note text;
alter table public.routine_days add column if not exists finisher text;
alter table public.routine_days add column if not exists type text;
alter table public.routine_days add column if not exists day_key text;
update public.routine_days set type = 'strength' where type is null;

alter table public.routine_day_exercises add column if not exists duration_seconds integer;
alter table public.routine_day_exercises add column if not exists role text;
alter table public.routine_day_exercises add column if not exists target_rir smallint;
alter table public.routine_day_exercises add column if not exists tempo text;
alter table public.routine_day_exercises add column if not exists progression_rule text;
alter table public.routine_day_exercises add column if not exists load_increment_kg numeric;
alter table public.routine_day_exercises add column if not exists notes text;
alter table public.routine_day_exercises add column if not exists alternative_exercise_ids text[];
alter table public.routine_day_exercises add column if not exists superset_group text;

-- New exercises used by the content plans (existing ids are left alone).
-- Weighted rows need weight_increase_kg (exercises_weight_increase_check).
insert into public.exercises (id, name, primary_muscle, secondary_muscles, equipment, cues, location_hint, weight_increase_kg) values
('forearm-plank', 'Forearm plank', 'core', '{}'::text[], 'bodyweight', ARRAY['Lift your body into a straight line from head to heels.', 'Squeeze your glutes and gently pull your belly button in.', 'Keep breathing.']::text[], 'Any mat in the stretching area or a quiet corner.', null),
('dumbbell-split-squat', 'Dumbbell split squat', 'quads', '{}'::text[], 'dumbbell', ARRAY['Lower your back knee straight down towards the floor.', 'Keep your front foot flat.', 'Push through your front foot to rise.']::text[], 'The dumbbell rack, usually along a mirrored wall in the free-weights area.', 2),
('bent-over-dumbbell-row', 'Bent-over dumbbell row', 'back', '{}'::text[], 'dumbbell', ARRAY['Row both dumbbells towards your lower ribs.', 'Keep your back flat throughout.', 'Lower slowly.']::text[], 'The dumbbell rack, usually along a mirrored wall in the free-weights area.', 2),
('overhead-dumbbell-triceps-extension', 'Overhead dumbbell triceps extension', 'triceps', '{}'::text[], 'dumbbell', ARRAY['Lower the dumbbell behind your head by bending your elbows.', 'Keep your elbows pointing up.', 'Straighten your arms to lift it back up.']::text[], 'An adjustable bench near the dumbbell rack, with dumbbells from the rack.', 2),
('single-arm-cable-row', 'Single-arm cable row', 'back', '{}'::text[], 'cable', ARRAY['Let your shoulder reach forward.', 'Pull the handle back towards your ribs.', 'Keep your hips and chest facing forward.']::text[], 'The cable station: a tall frame with adjustable pulleys and a choice of handles.', 1.25),
('triceps-pushdown', 'Triceps pushdown', 'triceps', '{}'::text[], 'cable', ARRAY['Push the handle down until your arms are straight.', 'Keep your elbows pinned to your sides.', 'Let it rise slowly to about chest height.']::text[], 'The cable station: a tall frame with adjustable pulleys and a choice of handles.', 1.25),
('face-pull', 'Face pull', 'shoulders', '{}'::text[], 'cable', ARRAY['Pull the rope towards your eyes, separating your hands.', 'Finish with your elbows high and hands beside your ears.', 'Return slowly.']::text[], 'The cable station: a tall frame with adjustable pulleys and a choice of handles.', 1.25),
('smith-machine-squat', 'Smith machine squat', 'quads', '{}'::text[], 'machine', ARRAY['Sit down between your heels.', 'Keep your back against an imaginary wall behind you.', 'Push up and twist the bar back onto the hooks when you finish.']::text[], 'Usually near the squat racks: a bar fixed on vertical rails.', 2.5),
('calf-raise-machine', 'Calf raise machine', 'calves', '{}'::text[], 'machine', ARRAY['Lower your heels slowly for a stretch.', 'Pause at the bottom.', 'Rise up as high as you can.']::text[], 'The resistance machine area. Standing or seated versions both work.', 2.5),
('pallof-press', 'Pallof press', 'core', '{}'::text[], 'cable', ARRAY['Press the handle straight out in front of you.', 'Don''t let the cable twist you towards the machine.', 'Bring it back to your chest slowly.']::text[], 'The cable station: a tall frame with adjustable pulleys.', 1.25),
('hammer-curl', 'Hammer curl', 'biceps', '{}'::text[], 'dumbbell', ARRAY['Curl the dumbbells up with your thumbs pointing up.', 'Keep your elbows by your sides.', 'Lower slowly.']::text[], 'The dumbbell rack, usually along a mirrored wall in the free-weights area.', 2),
('dumbbell-glute-bridge', 'Dumbbell glute bridge', 'glutes', '{}'::text[], 'dumbbell', ARRAY['Drive through your heels to lift your hips.', 'Squeeze your glutes hard at the top for a second.', 'Lower slowly.']::text[], 'On a mat in the stretching area or any quiet corner, with a dumbbell from the rack.', 2),
('farmer-carry', 'Farmer carry', 'core', '{}'::text[], 'dumbbell', ARRAY['Walk slowly with short, steady steps.', 'Keep your shoulders level and your chest up.', 'Put the dumbbells down carefully at the end.']::text[], 'The dumbbell rack, with a clear path of a few metres.', 2),
('dumbbell-box-squat', 'Dumbbell box squat', 'quads', '{}'::text[], 'dumbbell', ARRAY['Sit back until you lightly touch the bench.', 'Don''t relax onto it: keep your weight in your feet.', 'Stand up tall and squeeze your glutes.']::text[], 'Any flat bench or plyo box near the dumbbells.', 2),
('suitcase-carry', 'Suitcase carry', 'core', '{}'::text[], 'dumbbell', ARRAY['Walk slowly and stay upright.', 'Don''t lean towards or away from the weight.', 'Switch hands and repeat.']::text[], 'The dumbbell rack, with a clear path of a few metres.', 2),
('low-lunge-reach', 'Low lunge with reach', 'quads', '{}'::text[], 'bodyweight', ARRAY['From a kneeling lunge, reach the same-side arm up and over.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('worlds-greatest-stretch', 'World''s greatest stretch', 'core', '{}'::text[], 'bodyweight', ARRAY['Step into a lunge, hand inside your front foot, then reach that arm to the ceiling.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('standing-side-bend', 'Standing side bend', 'core', '{}'::text[], 'bodyweight', ARRAY['Reach one arm overhead and lean gently to the other side.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('shoulder-rolls', 'Shoulder rolls', 'shoulders', '{}'::text[], 'bodyweight', ARRAY['Roll your shoulders slowly up, back and down.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('hip-circles', 'Standing hip circles', 'core', '{}'::text[], 'bodyweight', ARRAY['Lift one knee and draw a slow circle out to the side.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('arm-circles', 'Arm circles', 'core', '{}'::text[], 'bodyweight', ARRAY['Small circles growing bigger, forwards then backwards.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('supported-deep-squat', 'Supported deep squat', 'quads', '{}'::text[], 'bodyweight', ARRAY['Hold a rack or bench and sink into a comfortable deep squat.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('knees-to-chest', 'Knees to chest', 'chest', '{}'::text[], 'bodyweight', ARRAY['Lie on your back and hug both knees in. Rock gently if it feels nice.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('supine-twist', 'Lying twist', 'core', '{}'::text[], 'bodyweight', ARRAY['Lie on your back and let both knees fall to one side.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('happy-baby', 'Happy baby', 'core', '{}'::text[], 'bodyweight', ARRAY['Lie on your back, hold your feet and let your knees drop wide.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('chin-tuck', 'Chin tuck', 'core', '{}'::text[], 'bodyweight', ARRAY['Sit tall and gently slide your chin straight back, like making a double chin.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('neck-side-stretch', 'Neck side stretch', 'core', '{}'::text[], 'bodyweight', ARRAY['Sit tall and tilt one ear towards your shoulder. Let your other shoulder drop.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('wrist-and-forearm-stretch', 'Wrist and forearm stretch', 'core', '{}'::text[], 'bodyweight', ARRAY['Arm straight, gently pull your fingers back, then down.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('frog-stretch', 'Frog stretch', 'core', '{}'::text[], 'bodyweight', ARRAY['On all fours, slide your knees wide and gently rock your hips back.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('supported-pigeon', 'Pigeon stretch', 'core', '{}'::text[], 'bodyweight', ARRAY['Front shin across the mat, back leg long. Use a rolled towel under your hip if needed.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('sphinx', 'Sphinx', 'core', '{}'::text[], 'bodyweight', ARRAY['Lie on your front and prop yourself up on your forearms. Relax your shoulders.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('slow-breathing', 'Slow breathing', 'core', '{}'::text[], 'bodyweight', ARRAY['Lie or sit comfortably. Breathe in for 4, out for 6.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('wall-angel', 'Wall angel', 'core', '{}'::text[], 'bodyweight', ARRAY['Back against a wall, slide your arms up and down like a snow angel.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('overhead-triceps-stretch', 'Overhead triceps stretch', 'triceps', '{}'::text[], 'bodyweight', ARRAY['Reach one hand down your back and gently press the elbow.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('kneeling-lat-stretch', 'Kneeling lat stretch', 'back', '{}'::text[], 'bodyweight', ARRAY['Kneel, place your hands on a bench and sink your chest down.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null),
('legs-up-the-wall', 'Legs up the wall', 'core', '{}'::text[], 'bodyweight', ARRAY['Lie with your legs resting up a wall. Arms relaxed by your sides.', 'Keep the range comfortable. Ask a gym instructor if you are unsure.', 'Breathe steadily. Never train through pain.']::text[], 'Ask a member of gym staff if you are not sure where this lives.', null)
on conflict (id) do nothing;

update public.exercises
set weight_increase_kg = case equipment
  when 'dumbbell' then 2
  when 'kettlebell' then 2
  when 'cable' then 1.25
  when 'machine' then 2.5
  when 'barbell' then 2.5
  else weight_increase_kg
end
where id in ('dumbbell-split-squat', 'bent-over-dumbbell-row', 'overhead-dumbbell-triceps-extension', 'single-arm-cable-row', 'triceps-pushdown', 'face-pull', 'smith-machine-squat', 'calf-raise-machine', 'pallof-press', 'hammer-curl', 'dumbbell-glute-bridge', 'farmer-carry', 'dumbbell-box-squat', 'suitcase-carry')
  and equipment not in ('bodyweight', 'band')
  and (weight_increase_kg is null or weight_increase_kg = 0);

