insert into public.routines (
  id, name, slug, description, cover_image_id, goal, length_weeks, days_per_week,
  session_minutes, difficulty, equipment, is_pro, is_featured_eligible, sort_order,
  type, audience_bullets, by_the_end_bullets, split_note, progression_note
) values
('30-day-glute-challenge', '30-Day Glute Challenge', '30-day-glute-challenge', 'Thirty days, twelve sessions, all about building strong glutes. Two lower-body days and one upper-body day each week.', 'glute-challenge-cover', 'glutes_legs', 4, 3, 40, 'beginner', 'full_gym', true, true, 1, 'strength', ARRAY['You want a short, focused goal to get stuck into', 'Glutes and legs are your priority', 'You can train three times a week']::text[], ARRAY['Feel confident with hip thrusts and Romanian deadlifts', 'Lift more on your hip thrust than on day one', 'Know which glute exercises you enjoy most']::text[], 'Your glutes respond well to being trained twice a week from different angles: hip thrusts and hinges on one day, squats and single-leg work on the other. One upper-body day keeps you balanced.', 'Hit the top of the rep range on every set and we''ll suggest more weight. Glute isolation moves add reps first.'),
('busy-gym-no-problem', 'Busy Gym? No Problem', 'busy-gym-no-problem', 'Every exercise uses a bench and dumbbells, so you never wait for a machine. Perfect for 6pm on a Monday.', 'busy-gym-cover', 'strength', 6, 3, 45, 'beginner', 'dumbbells', true, true, 2, 'strength', ARRAY['Your gym is busy when you can go', 'You''d rather stay in one spot', 'You want a proper strength plan without the queues']::text[], ARRAY['A routine you can do whenever, however busy', 'Stronger on your key dumbbell lifts', 'Confident with Bulgarian split squats']::text[], 'Dumbbells and a bench can train every movement pattern well. Three full-body days give you plenty of practice and you never have to move around the gym.', 'When you hit the top of the range, grab the next dumbbells up.'),
('glutes-and-legs-in-8-weeks', 'Glutes and Legs in 8 Weeks', 'glutes-and-legs-in-8-weeks', 'Two lower-body days built around your glutes and two upper-body days to keep you balanced. Built for real, steady progress.', 'glutes-legs-cover', 'glutes_legs', 8, 4, 50, 'intermediate', 'full_gym', true, true, 3, 'strength', ARRAY['You''ve trained consistently for a few months', 'Glutes and legs are your main focus', 'You can train four days a week']::text[], ARRAY['Hip thrust and Romanian deadlift noticeably heavier', 'Confident with Bulgarian split squats and the Smith machine', 'A balanced upper body to match']::text[], 'An upper and lower split lets you train your lower body hard twice a week with plenty of recovery. Each lower day hits your glutes from a different angle.', 'Main lifts go up when you hit the top of the range on every set. Glute isolation and accessories add reps first.'),
('higher-ground', 'Higher Ground', 'higher-ground', 'Squat, deadlift and bench with a barbell, built around four well-balanced days. The plan for when you''re ready to own the whole gym.', 'higher-ground-cover', 'strength', 8, 4, 55, 'intermediate', 'full_gym', true, true, 4, 'strength', ARRAY['You''ve trained regularly for six months or more', 'You''re ready to learn the barbell squat and bench press', 'You can train four days a week']::text[], ARRAY['Squat, trap bar deadlift and bench press with confidence', 'Clearly stronger on all three', 'Comfortable in the squat rack area']::text[], 'Upper and lower days let you train each big lift with full focus and recover well between sessions. Each muscle is trained twice a week.', 'Barbell lifts go up 2.5 kg when you hit the top of the range on every set. Accessories add reps first.'),
('machines-made-easy', 'Machines Made Easy', 'machines-made-easy', 'Machines guide the movement for you, which makes them a brilliant way to start. Learn the main ones, one session at a time.', 'machines-cover', 'confidence', 4, 3, 40, 'beginner', 'full_gym', true, true, 5, 'strength', ARRAY['You''re brand new to the gym', 'You''d like to start with machines before free weights', 'You want to know what every machine actually does']::text[], ARRAY['Know how to set up and use about 15 machines', 'Have favourites you can rely on when the gym is busy', 'Be ready for a dumbbell-based plan']::text[], 'Three full-body machine circuits cover every major muscle. Machines guide the movement, so you can focus on effort and set-up rather than balance.', 'Add one plate when you hit the top of the range on every set.'),
('quick-ascent', 'Quick Ascent', 'quick-ascent', 'In and out in 30 minutes. Exercises are paired up so you rest less and still train your whole body.', 'quick-ascent-cover', 'strength', 6, 3, 30, 'beginner', 'dumbbells', true, true, 6, 'strength', ARRAY['You''re short on time', 'You''d rather train often and briefly', 'You know the basics of dumbbells']::text[], ARRAY['A 30-minute routine you can fit into any day', 'Stronger on your key lifts', 'Fitter, with less rest between sets']::text[], 'Pairing exercises that use different muscles (like a squat with a row) means one recovers while the other works. You get a full session''s work in about half the time.', 'Hit the top of the range on every set and we''ll suggest more weight.'),
('strength-and-stamina', 'Strength and Stamina', 'strength-and-stamina', 'For when you love cardio as much as lifting. Two solid full-body strength days, a steady cardio day and an interval day each week.', 'strength-and-stamina-cover', 'general', 6, 2, 55, 'intermediate', 'full_gym', true, true, 7, 'strength', ARRAY['You''ve been training for a while and know the main lifts', 'You enjoy cardio and want it to be a real part of your plan', 'You can train four times a week, with two of those being cardio']::text[], ARRAY['Lift heavier on your trap bar deadlift and squat', 'Handle harder interval sessions with confidence', 'Have a balanced week that builds strength and fitness together']::text[], 'Two full-body strength sessions are enough to keep getting stronger when you train them hard and progress them well. Keeping cardio on separate days means your lifts get your full effort, and the interval day builds fitness quickly.', 'Strength: hit the top of the rep range on every set and we''ll suggest more weight. Cardio: add a round or a few minutes first, then effort.'),
('strong-and-fit-in-8-weeks', 'Strong and Fit in 8 Weeks', 'strong-and-fit-in-8-weeks', 'Get stronger and fitter at the same time. Three full-body strength sessions and two cardio sessions a week, with a recovery day in between.', 'strong-and-fit-cover', 'general', 8, 3, 45, 'beginner', 'dumbbells', true, true, 8, 'strength', ARRAY['You''d like your fitness and strength to improve together', 'You enjoy cardio, or you''re happy to give it a go', 'You''ve trained a little and know your way around the basics']::text[], ARRAY['Lift more on your key lifts than in week 1', 'Walk, cycle or row for longer, and at a higher effort, than when you started', 'Have a balanced week you can keep doing']::text[], 'Three full-body strength days train every muscle often, while two cardio days build your heart and lung fitness. Strength and cardio sit on different days so each one gets your full effort, and a recovery day keeps the week sustainable.', 'Strength: hit the top of the rep range on every set and we''ll suggest more weight next time. Cardio: add minutes first, then effort.'),
('strong-for-life', 'Strong for Life', 'strong-for-life', 'Steady, joint-friendly strength training with carries and balance work. The kind of strength that makes everyday life easier.', 'strong-for-life-cover', 'general', 8, 2, 45, 'beginner', 'dumbbells', true, true, 9, 'strength', ARRAY['You want to stay strong and capable long term', 'You prefer a gentle, steady pace', 'You can train twice a week']::text[], ARRAY['Feel stronger carrying, climbing stairs and lifting', 'Better balance on one leg', 'A sustainable routine you can keep for years']::text[], 'Two full-body sessions with plenty of recovery suit a steady approach. Machines and dumbbells keep the movements controlled, and carries and step-ups build everyday strength and balance.', 'Small, steady increases when you hit the top of the range on every set. No rush.'),
('strong-foundations-6-weeks', 'Strong Foundations in 6 Weeks', 'strong-foundations-6-weeks', 'Start in one quiet spot with a bench and dumbbells. Each fortnight you''ll add a little more of the gym, until it all feels familiar.', 'strong-foundations-cover', 'confidence', 6, 3, 45, 'beginner', 'full_gym', false, true, 10, 'strength', ARRAY['You''re new to the gym, or coming back after a long break', 'You''d like a clear plan so you never have to guess what to do next', 'You want to feel comfortable in the weights area, not just the treadmill']::text[], ARRAY['Know your way around dumbbells, the most common machines and a barbell', 'Lift noticeably more on your key lifts than in week 1', 'Have a 3-day routine you can walk in and do with confidence']::text[], 'Three full-body sessions a week means you practise every movement more than once a week, which is the fastest way to learn them. Each session trains your legs, upper body and core, so missing a day never leaves a gap.', 'When you hit the top of the rep range on every set with good form, we''ll suggest a little more weight next time. Until then, aim for one more rep than last time.'),
('summit', 'Summit', 'summit', 'Heavier barbell work and lower reps for women who already lift confidently. Your strongest eight weeks yet.', 'summit-cover', 'strength', 8, 4, 60, 'experienced', 'full_gym', true, true, 11, 'strength', ARRAY['You''ve lifted consistently for a year or more', 'You''re confident with the barbell squat, deadlift and bench', 'You want to push your numbers higher']::text[], ARRAY['New personal bests on your big lifts', 'Comfortable working in the 4 to 6 rep range', 'A stronger hip thrust to match']::text[], 'Upper and lower days with one heavy main lift each let you push hard and recover well. Phase two drops to lower reps for maximum strength.', 'Main lifts go up 2.5 kg when you hit the top of the range on every set with good form.'),
('the-climb-in-8-weeks', 'The Climb in 8 Weeks', 'the-climb-in-8-weeks', 'You know your way around. Now it''s time to get properly strong, with heavier main lifts and a plan that builds every week.', 'the-climb-cover', 'strength', 8, 3, 50, 'beginner', 'full_gym', true, true, 12, 'strength', ARRAY['You''ve finished Strong Foundations or trained for a few months', 'You''re comfortable with dumbbells and common machines', 'You want to see your numbers really climb']::text[], ARRAY['Lift noticeably heavier on your main lifts', 'Be confident with a barbell Romanian deadlift and hip thrust', 'Understand how to push hard while keeping good form']::text[], 'Three full-body days let you practise the big lifts often while recovering well. The second phase lowers the reps and adds a set to your main lifts, which is how strength really builds.', 'Hit the top of the rep range on every set and we''ll suggest more weight next time. Main lifts go up in small jumps; accessories add reps first.'),
('the-two-day-start', 'The Two-Day Start', 'the-two-day-start', 'Only got two days? Two full-body sessions a week is plenty to get stronger and feel at home in the gym.', 'two-day-start-cover', 'confidence', 6, 2, 45, 'beginner', 'dumbbells', false, true, 13, 'strength', ARRAY['You''re new to the gym or coming back after a break', 'You can realistically train twice a week', 'You''d like a plan that fits around a busy life']::text[], ARRAY['Have a two-day routine that fits your week', 'Know your way around dumbbells and the most common machines', 'Lift more on your key lifts than in week 1']::text[], 'Two full-body sessions mean every muscle gets trained twice a week, which is enough to build strength when you''re starting out. Each session covers squat, hinge, push and pull, so nothing gets left behind.', 'When you hit the top of the rep range on every set, we''ll suggest a little more weight next time. Until then, aim for one more rep.'),
('upper-body-strong-in-6-weeks', 'Upper Body Strong in 6 Weeks', 'upper-body-strong-in-6-weeks', 'Two upper-body days and one lower-body day each week. Build a strong back, shoulders and arms, and stand a little taller.', 'upper-body-cover', 'strength', 6, 3, 45, 'beginner', 'dumbbells', true, true, 14, 'strength', ARRAY['You''d like a stronger upper body', 'You want to work on posture and your back', 'You still want one leg day each week']::text[], ARRAY['Lift more on your bench press, pulldown and shoulder press', 'Feel your back muscles working when you row', 'Be able to do more push-ups than in week 1']::text[], 'Two upper days give your back, shoulders and arms enough practice to get stronger, with extra pulling work for posture. One lower day keeps your legs and glutes ticking over.', 'When you hit the top of the range on every set, we''ll suggest a little more weight. Arms and shoulders add reps first.'),
('welcome-back-4-week-restart', 'Welcome Back: 4-Week Restart', 'welcome-back-4-week-restart', 'Been away for a while? This gently rebuilds your routine and your strength, so you feel like yourself again in the gym.', 'welcome-back-cover', 'confidence', 4, 3, 40, 'beginner', 'dumbbells', true, false, 15, 'strength', ARRAY['You''ve had a break of a month or more', 'You used to train and want to get back into it', 'You''d like a short, gentle restart']::text[], ARRAY['A three-day routine back in your week', 'Your strength heading back to where it was', 'Ready to start a longer plan']::text[], 'Three full-body sessions with conservative weights rebuild your habit and strength without the soreness that puts people off coming back.', 'Start lighter than you used to lift. We''ll suggest increases as your sets feel easier.'),
('stretch-morning', 'Morning Mobility', 'morning-mobility', 'A gentle 11-minute flow to loosen everything up first thing. No equipment, just a mat.', 'morning-mobility-cover', 'general', 1, 1, 11, 'beginner', 'full_gym', true, true, 80, 'stretch', ARRAY['You feel stiff in the mornings', 'You want an easy way to start the day moving', 'You''d like a stretch habit that takes 10 minutes']::text[], '{}'::text[], 'Move slowly and breathe through every stretch. You should feel looser at the end, not tired.', null),
('stretch-post-leg', 'After Leg Day', 'after-leg-day', 'The perfect way to finish a lower-body session, or to loosen up the day after.', 'after-leg-day-cover', 'general', 1, 1, 11, 'beginner', 'full_gym', true, true, 81, 'stretch', ARRAY['You''ve just trained legs or glutes', 'Your legs feel tight the day after training', 'You want a calm 10 minutes to finish your session']::text[], '{}'::text[], 'Hold each stretch somewhere between a gentle pull and comfortable. Never force it.', null),
('stretch-desk', 'Desk Reset', 'desk-reset', 'Undo a long day of sitting. Most of it can be done standing, so it works anywhere.', 'desk-reset-cover', 'general', 1, 1, 6, 'beginner', 'full_gym', true, true, 82, 'stretch', ARRAY['You sit at a desk or study for long periods', 'Your neck and shoulders feel tight', 'You want something quick you can do anywhere']::text[], '{}'::text[], 'Small, slow movements work best here. Keep breathing and keep it comfortable.', null),
('stretch-hips', 'Happy Hips', 'happy-hips', 'A slower session all about your hips. Great before a squat day or on a rest day.', 'happy-hips-cover', 'general', 1, 1, 11, 'beginner', 'full_gym', true, true, 83, 'stretch', ARRAY['Your hips feel tight or stuck', 'You''d like more comfortable depth in squats', 'You sit a lot during the day']::text[], '{}'::text[], 'Hip stretches can feel intense. Ease off if you feel anything sharp, and use a towel for support wherever you like.', null),
('stretch-lower-back', 'Back Unwind', 'back-unwind', 'Gentle movements to help your back feel looser after sitting, standing or training.', 'back-unwind-cover', 'general', 1, 1, 10, 'beginner', 'full_gym', true, true, 84, 'stretch', ARRAY['Your back feels stiff after a long day', 'You''d like a gentle, slow session', 'You want to move your spine in every direction']::text[], '{}'::text[], 'Keep every movement gentle. If you have back pain, check with your GP or a physiotherapist before doing this session.', null),
('stretch-upper', 'Shoulders and Upper Back', 'shoulders-and-upper-back', 'Release your chest, shoulders and upper back. A natural partner to any upper-body day.', 'shoulders-cover', 'general', 1, 1, 10, 'beginner', 'full_gym', true, true, 85, 'stretch', ARRAY['You''ve just trained upper body', 'You''d like to sit and stand a little taller', 'Your shoulders feel rounded or tight']::text[], '{}'::text[], 'Let your breathing do the work. Each breath out, sink a little further into the stretch.', null),
('stretch-full-body', 'Full-Body Recovery Flow', 'full-body-recovery-flow', 'A longer, slower session for recovery days. Every major area, with time to breathe.', 'recovery-flow-cover', 'general', 1, 1, 20, 'beginner', 'full_gym', true, true, 86, 'stretch', ARRAY['You''re on a recovery day in your routine', 'You want something gentle that still counts', 'You''d like a calm 20 minutes']::text[], '{}'::text[], 'There''s no rush today. Take extra breaths in any stretch that feels good.', null),
('wind-down', 'Wind Down', 'wind-down', 'Slow, floor-based stretches and breathing. A calm way to finish your day.', 'wind-down-cover', 'general', 1, 1, 11, 'beginner', 'full_gym', true, true, 87, 'stretch', ARRAY['You like to switch off in the evening', 'You prefer slow, relaxing sessions', 'You want stretches you can do lying down']::text[], '{}'::text[], 'Dim the lights if you can. Breathe out for longer than you breathe in.', null)
on conflict (id) do update set
  name = excluded.name,
  slug = excluded.slug,
  description = excluded.description,
  cover_image_id = excluded.cover_image_id,
  goal = excluded.goal,
  length_weeks = excluded.length_weeks,
  days_per_week = excluded.days_per_week,
  session_minutes = excluded.session_minutes,
  difficulty = excluded.difficulty,
  equipment = excluded.equipment,
  is_pro = excluded.is_pro,
  is_featured_eligible = excluded.is_featured_eligible,
  sort_order = excluded.sort_order,
  type = excluded.type,
  audience_bullets = excluded.audience_bullets,
  by_the_end_bullets = excluded.by_the_end_bullets,
  split_note = excluded.split_note,
  progression_note = excluded.progression_note;

